import Mathlib

def TokenUnits (t d v : ℝ) : ℝ := d + 2*(6*d^2+2*t*d+4*t-1+3*d)+d*v+v-1

def Claim : Prop := ∀ v : ℝ, 1 ≤ v → ∃ c C : ℝ, 0 < c ∧ 0 < C ∧ ∀ t d : ℝ, 1 ≤ t → 1 ≤ d → c*(t*d+d^2) ≤ TokenUnits t d v ∧ TokenUnits t d v ≤ C*(t*d+d^2)

import Mathlib

def StoredWords (n d : ℝ) : ℝ := 4*n*d+d+1

def Claim : Prop := ∃ c C : ℝ, 0 < c ∧ 0 < C ∧ ∀ n d : ℝ, 1 ≤ n → 1 ≤ d → c*(n*d) ≤ StoredWords n d ∧ StoredWords n d ≤ C*(n*d)

import Mathlib

def SequenceUnits (n d v : ℝ) : ℝ := (2*d+4)*n*(n+1)+n*(12*d^2+7*d+d*v+v-3)

def Claim : Prop := ∀ v : ℝ, 1 ≤ v → ∃ c C : ℝ, 0 < c ∧ 0 < C ∧ ∀ n d : ℝ, 1 ≤ n → 1 ≤ d → c*(n^2*d+n*d^2) ≤ SequenceUnits n d v ∧ SequenceUnits n d v ≤ C*(n^2*d+n*d^2)

import Mathlib

def DirectPositionAccess (N M : ℕ) : Prop :=
  ∃ access : Fin N → Fin M, ∀ t : Fin N, (access t).val = t.val

def Claim : Prop :=
  (∀ N : ℕ, N ≤ 4096 → DirectPositionAccess N 4096) ∧
  ¬ DirectPositionAccess 4097 4096
